package com.youlong.hd;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** User-granted document-tree cleanup. Nothing is selected or deleted automatically. */
public final class FolderCleanupActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final List<Item> items=new ArrayList<>();private TextView report;private volatile boolean busy;private Spinner scope;
 private static final class Item{final Uri uri;final String name;final long size,modified;Item(Uri uri,String name,long size,long modified){this.uri=uri;this.name=name;this.size=size;this.modified=modified;}}
 @Override public void onCreate(Bundle state){setTheme(R.style.Theme_ClearGuard_Native);super.onCreate(state);NativeUi.Page page=new NativeUi.Page(this,"文件夹清理","选择目录、查看文件、逐项确认。","只处理通过系统文件选择器授权的目录。默认寻找安装包、临时文件和日志，不自动选择任何文件。你也可以查看全部文件并手动选择。删除无法撤销；模型、照片和文档只有你在全部文件中明确勾选才会被删除。文件自预览后发生变化时跳过，单次最多列出 2000 个文件。");
  LinearLayout area=page.section("扫描范围");scope=new Spinner(this);scope.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"安装包、临时文件与日志","全部文件（只手动选择）"}));NativeUi.field(this,area,"查找类型",scope);NativeUi.action(this,area,"选择文件夹并检查  ↗",()->{if(!busy)startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION),86);},true);
  LinearLayout results=page.section("预览结果");report=new TextView(this);report.setText("尚未选择文件夹，不会扫描或删除你的文件。");NativeUi.report(this,results,report,false);NativeUi.action(this,results,"查看并选择要删除的文件",this::choose,false);page.show();
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=86||result!=RESULT_OK||data==null||data.getData()==null)return;Uri tree=data.getData();boolean all=scope.getSelectedItemPosition()==1;busy=true;report.setText("正在检查授权目录…");worker.execute(()->{try{items.clear();ArrayDeque<String> pending=new ArrayDeque<>();Set<String> visited=new HashSet<>();pending.add(DocumentsContract.getTreeDocumentId(tree));boolean limited=false;long bytes=0;int examined=0;
   while(!pending.isEmpty()){if(Thread.currentThread().isInterrupted())return;String parent=pending.remove();if(!visited.add(parent))continue;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,parent);try(Cursor c=getContentResolver().query(children,new String[]{"document_id","_display_name","mime_type","_size","last_modified"},null,null,null)){if(c==null)throw new IOException("文件提供程序未返回目录");while(c.moveToNext()){if(Thread.currentThread().isInterrupted())return;if(++examined>100000){limited=true;pending.clear();break;}String id=c.getString(0),name=c.getString(1),type=c.getString(2);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(type)){if(visited.size()+pending.size()>2000){limited=true;continue;}pending.add(id);continue;}if(items.size()>=2000){limited=true;break;}if(!all&&!temporary(name))continue;long size=c.isNull(3)?0:c.getLong(3),modified=c.isNull(4)?0:c.getLong(4);items.add(new Item(DocumentsContract.buildDocumentUriUsingTree(tree,id),name,size,modified));bytes+=size;}}if(items.size()>=2000){limited=true;break;}}
   String text="找到文件："+items.size()+"\n合计大小："+android.text.format.Formatter.formatFileSize(this,bytes)+(limited?"\n达到条目上限，结果不完整":"")+"\n没有文件被自动选中或删除。";show(text);
  }catch(Exception error){items.clear();show("检查未完成："+error.getMessage());}finally{busy=false;}});}
 static boolean temporary(String name){if(name==null)return false;String s=name.toLowerCase(Locale.ROOT);return s.endsWith(".apk")||s.endsWith(".apks")||s.endsWith(".xapk")||s.endsWith(".tmp")||s.endsWith(".temp")||s.endsWith(".cache")||s.endsWith(".log")||s.endsWith(".bak");}
 private void show(String text){runOnUiThread(()->{if(!isDestroyed())report.setText(text);});}
 private void choose(){if(busy)return;if(items.isEmpty()){report.setText("没有可选文件，请先检查目录或调整查找类型。");return;}List<Item> snapshot=new ArrayList<>(items),selected=new ArrayList<>();String[] labels=new String[snapshot.size()];for(int i=0;i<labels.length;i++)labels[i]=snapshot.get(i).name+" · "+android.text.format.Formatter.formatFileSize(this,snapshot.get(i).size);
  new AlertDialog.Builder(this).setTitle("手动勾选要删除的文件").setMultiChoiceItems(labels,new boolean[labels.length],(d,i,on)->{if(on)selected.add(snapshot.get(i));else selected.remove(snapshot.get(i));}).setNegativeButton("取消",null).setPositiveButton("预览删除",(d,w)->{if(selected.isEmpty()){report.setText("没有选择文件，未进行删除。");return;}StringBuilder names=new StringBuilder();long bytes=0;for(int i=0;i<selected.size();i++){bytes+=selected.get(i).size;if(i<12)names.append(selected.get(i).name).append('\n');}new AlertDialog.Builder(this).setTitle("删除 "+selected.size()+" 个文件？").setMessage("合计 "+android.text.format.Formatter.formatFileSize(this,bytes)+"，无法撤销。\n\n"+names+(selected.size()>12?"其余文件已在上一页逐项勾选。":"")).setNegativeButton("保留",null).setPositiveButton("确认删除",(dialog,which)->remove(selected)).show();}).show();
 }
 private void remove(List<Item> selected){busy=true;report.setText("正在删除你选择的文件…");worker.execute(()->{long bytes=0;int removed=0,skipped=0;for(Item item:selected){if(Thread.currentThread().isInterrupted())break;try(Cursor c=getContentResolver().query(item.uri,new String[]{"_display_name","_size","last_modified"},null,null,null)){if(c==null||!c.moveToFirst()||!item.name.equals(c.getString(0))||item.size!=c.getLong(1)||(item.modified!=0&&item.modified!=c.getLong(2))){skipped++;continue;}if(DocumentsContract.deleteDocument(getContentResolver(),item.uri)){removed++;bytes+=item.size;}else skipped++;}catch(Exception error){skipped++;}}items.removeAll(selected);busy=false;show("删除成功："+removed+" 个\n释放空间："+android.text.format.Formatter.formatFileSize(this,bytes)+"\n失败或已变化而跳过："+skipped+"\n只计算确认删除成功的文件。");});}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
